//   npm run cy:visual:capture
//   — or —
//   npx cypress run --spec "cypress/e2e/visual/**" --env updateSnapshots=true
//
// COMPARE against baseline (CI / regression check):
//   npm run cy:visual:compare
//
// IMPORTANT: Always capture and compare on the SAME OS and browser engine.
//   Commit cypress/snapshots/baseline/ to git — that is the visual contract.
//   Never commit cypress/snapshots/diff/ or cypress/snapshots/comparison/.
//
// Viewport: 1600x900 (matches cypress.config.js)
// Threshold: 0.1% (set in cypress.config.js env.cypressImageDiff.errorThreshold)

import LoginPage from '../../support/pages/LoginPage';
import NavigationComponent from '../../support/pages/NavigationComponent';

// ─── Dynamic content masking ──────────────────────────────────────────────────
// Hides elements whose content changes between runs to prevent false positives.
const maskDynamicContent = () => {
  // User avatar / name in top navigation bar
  cy.get('[class*="userdropdown-tab"]', { timeout: 3000 }).then(($el) => {
    if ($el.length) cy.wrap($el).invoke('css', 'visibility', 'hidden');
  });
};

// ─── Snapshot helper ──────────────────────────────────────────────────────────
const captureSnapshot = (name) => {
  // Allow Vue transitions to settle before capturing
  // eslint-disable-next-line cypress/no-unnecessary-waiting
  cy.wait(800);
  maskDynamicContent();
  cy.compareSnapshot(name);
};

// ─── Public pages (no auth required) ─────────────────────────────────────────

describe('Visual Baseline — Public Pages', () => {

  it('Login page — desktop 1600x900', () => {
    LoginPage.visit();
    captureSnapshot('login-page-desktop');
  });

  it('Reset Password page — desktop 1600x900', () => {
    LoginPage.visit();
    LoginPage.clickForgotPassword();
    cy.url().should('include', '/auth/requestPasswordResetCode');
    captureSnapshot('reset-password-page-desktop');
  });
});

// ─── Authenticated pages ──────────────────────────────────────────────────────

describe('Visual Baseline — Authenticated Pages', () => {

  beforeEach(() => {
    cy.loginWithEnvCredentials();
  });

  it('Dashboard — desktop 1600x900', () => {
    cy.url().should('include', '/dashboard');
    captureSnapshot('dashboard-desktop');
  });

  it('Admin — System Users page — desktop 1600x900', () => {
    NavigationComponent.navigateToAdmin();
    cy.get('.oxd-table-body', { timeout: 5000 }).should('be.visible');
    // Mask table rows — demo data changes between runs
    cy.get('.oxd-table-body .oxd-table-row').invoke('css', 'visibility', 'hidden');
    captureSnapshot('admin-system-users-desktop');
  });

  it('Admin — Add User form — desktop 1600x900', () => {
    NavigationComponent.navigateToAdmin();
    cy.contains('button', 'Add').click();
    cy.url().should('include', '/saveSystemUser');
    captureSnapshot('admin-add-user-form-desktop');
  });

  it('PIM — Employee List page — desktop 1600x900', () => {
    NavigationComponent.navigateToPIM();
    cy.get('.oxd-table-body', { timeout: 5000 }).should('be.visible');
    cy.get('.oxd-table-body .oxd-table-row').invoke('css', 'visibility', 'hidden');
    captureSnapshot('pim-employee-list-desktop');
  });

  it('PIM — Add Employee form — desktop 1600x900', () => {
    NavigationComponent.navigateToPIM();
    cy.contains('button', 'Add').click();
    cy.url().should('include', '/addEmployee');
    captureSnapshot('pim-add-employee-form-desktop');
  });

  it('Leave — Leave List page — desktop 1600x900', () => {
    NavigationComponent.navigateToLeave();
    cy.get('.oxd-table', { timeout: 5000 }).should('be.visible');
    cy.get('.oxd-table-body').invoke('css', 'visibility', 'hidden');
    captureSnapshot('leave-list-desktop');
  });

  it('Leave — Apply Leave form — desktop 1600x900', () => {
    NavigationComponent.navigateToLeave();
    NavigationComponent.navigateToApplyLeave();
    cy.url().should('include', '/applyLeave');
    captureSnapshot('leave-apply-form-desktop');
  });
});

/*
──────────────────────────────────────────────────────────────────────────────
HOW TO UPDATE BASELINES AFTER AN APPROVED UI CHANGE
──────────────────────────────────────────────────────────────────────────────

1. Confirm the change is intentional.
2. npm run cy:visual:capture   (or: npx cypress run --spec "cypress/e2e/visual/**" --env updateSnapshots=true)
3. git add cypress/snapshots/baseline/
4. git commit -m "chore: update visual baseline after [description]"

NEVER run updateSnapshots=true in CI automatically.

──────────────────────────────────────────────────────────────────────────────
KNOWN LIMITATIONS (third-party demo app)
──────────────────────────────────────────────────────────────────────────────

- Demo data changes: table rows are masked; other dynamic content may vary.
  If false positives occur, increase errorThreshold to 0.5 in cypress.config.js.
- OS differences: baselines differ between macOS and Linux.
  Establish the canonical baseline on the CI runner (Ubuntu + Chrome).
- Vue transitions: 800ms settle wait covers most animations.
──────────────────────────────────────────────────────────────────────────────
*/
